-- DRNAS SAT incremental audited evidence, 2026-11-07.
-- Apply AFTER research/drnas_sat_benchmark_history_20261106.sql; within-cohort PAR-2 only.
-- Evidence comes from GitHub Actions FINAL audit logs; do not interpret timeout ratios as finite speedups.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS benchmark_cohorts (cohort_id TEXT PRIMARY KEY, version TEXT NOT NULL, cohort_type TEXT NOT NULL, github_run_id INTEGER NOT NULL UNIQUE, original_formulas INTEGER, total_attempts INTEGER, audit_status TEXT NOT NULL, source_url TEXT NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS benchmark_modes (cohort_id TEXT NOT NULL REFERENCES benchmark_cohorts(cohort_id), mode TEXT NOT NULL, trials INTEGER NOT NULL, solved INTEGER NOT NULL, par2_s REAL NOT NULL, measured_wall_s REAL, PRIMARY KEY (cohort_id,mode), CHECK(solved<=trials),CHECK(par2_s>=0));
CREATE TABLE IF NOT EXISTS build_status (version TEXT PRIMARY KEY, branch TEXT NOT NULL, status TEXT NOT NULL, last_evidence_url TEXT NOT NULL, notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_structure_audits (run_id INTEGER PRIMARY KEY, description TEXT NOT NULL, original_formulas INTEGER NOT NULL, mean_scan_ms REAL, max_scan_ms REAL, tags_json TEXT NOT NULL, audit_status TEXT NOT NULL, source_url TEXT NOT NULL, notes TEXT NOT NULL);
COMMIT;
